```spl
index=web_proxy sourcetype=apache:access host="web-proxy-01"
| where match(_raw, "(?i)\$\{jndi:(ldap|rmi|dns|nis|iiop):")
| stats count min(_time) as first_seen max(_time) as last_seen by src_ip, uri, status, useragent
```
```elasticsearch
GET /logs-security-*/_search
{
  "query": {
    "bool": {
      "must": [
        { "term": { "asset_id": "SRV-WEB-001" } },
        { "query_string": { "query": "*jndi* OR *ldap*" } }
      ]
    }
  }
}
```

```spl
index=firewall host="vpn-gateway-01" sourcetype=pan:os
| regex _raw="(?i)device_telemetry|globalprotect.*(cookie|sessid)"
| table _time, src_ip, action, url, status
```
```elasticsearch
GET /logs-firewall-*/_search
{
  "query": {
    "bool": {
      "must": [
        { "term": { "asset_id": "SRV-VPN-001" } },
        { "query_string": { "query": "*CVE-2024-3400* OR *telemetry*" } }
      ]
    }
  }
}
```

```spl
index=vpn sourcetype=citrix:netscaler host="vpn-gateway-01"
| regex _raw="GET /oauth/idp/\.well-known/openid-configuration"
| eval host_header_len=len(host_header)
| where host_header_len > 1024
| table _time, src_ip, host_header_len, status
```
```elasticsearch
GET /logs-vpn-*/_search
{
  "query": {
    "bool": {
      "must": [
        { "term": { "asset_id": "SRV-VPN-001" } },
        { "query_string": { "query": "*openid-configuration*" } }
      ]
    }
  }
}
```

```spl
index=network host="web-proxy-01" dest_port=8009
| stats count by src_ip, dest_port, protocol
| sort - count
```
```elasticsearch
GET /logs-network-*/_search
{
  "query": {
    "bool": {
      "must": [
        { "term": { "asset_id": "SRV-WEB-001" } },
        { "query_string": { "query": "*dest_port: 8009*" } }
      ]
    }
  }
}
```
